  m.stages[0].failedFixes = [
    { defectId: 'D1', deterministic: true, status: 'FAIL' },
    { defectId: 'D1', deterministic: true, status: 'FAIL' },
  ]
  const snap = { planSha256: H, sourceSha256: H, configSha256: H, scopeSha256: scopeFingerprint(m) }
  const mk = (kind) => ({
    kind,
    status: 'PASS',
    complete: true,
    scope: 'full',
    artifact: { path: `evidence/${kind}.json`, sha256: H },
    bindings: { planSha256: H, scopeSha256: snap.scopeSha256 },
  })
  const refs = {
    policyDecision: mk('policyDecision'),
    checkpoint: mk('checkpoint'),
    pre: mk('pre'),
    red: mk('red'),
  }
  const trusted = new WeakSet(Object.values(refs))
  const boundary = createEvidenceBoundary({ verify: async (_kind, ref) => trusted.has(ref) })
  const args = {
    manifest: m,
    stageId: 'W01',
    target: 'IMPLEMENTATION',
    evidence: refs,
    boundary,
    snapshot: snap,
  }
  assert.ok(issue(await evaluateTransition(args), 'RCA_REQUIRED'))
  m.stages[0].rca = {
    defectId: 'D1',
    classification: 'ALGORITHM',
    root: 'wrong transition decision',
    layer: 'domain',
    artifact: { path: 'evidence/rca.json', sha256: H },
  }
  assert.ok(issue(await evaluateTransition(args), 'RCA_PROOF'))
  refs.rca = {
    ...mk('rca'),
    bindings: {
      ...mk('rca').bindings,
      defectId: 'D1',
      classification: 'ALGORITHM',
      root: m.stages[0].rca.root,
      layer: m.stages[0].rca.layer,
    },
  }
  assert.ok(issue(await evaluateTransition(args), 'RCA_PROOF'))
  trusted.add(refs.rca)
  assert.equal((await evaluateTransition(args)).ok, true)
  m.stages[0].rca.root = 'a different incorrect transition decision'
  assert.ok(issue(await evaluateTransition(args), 'RCA_PROOF'))
})

