test('FWE-004-S01 traced PASS text needs trusted current run proof', async () => {
  const t = trace()
  t.requirements[0].scenarioIds.push('FWE-004-S02', 'FWE-004-S03')
  const current = { sourceSha256: H, configSha256: H }
  const run = t.runs[0]
  const accepted = new WeakSet([run])
  const boundary = createEvidenceBoundary({
    verify: async (kind, ref, expected) =>
      kind === 'run' &&
      accepted.has(ref) &&
      Object.entries(expected).every(([k, v]) => ref.bindings[k] === v),
  })
  assert.ok(issue(await verifyTraceability(t, { boundary, snapshot: current }), 'TRACE_RUN_PROOF'))
  Object.assign(run, {
    kind: 'run',
    scope: 'full',
    complete: true,
    artifact: { path: 'evidence/run.json', sha256: H },
    bindings: current,
  })
  assert.equal((await verifyTraceability(t, { boundary, snapshot: current })).ok, true)
  t.runs.push({
    id: 'historical-fail',
    sourceSha256: H,
    configSha256: H,
    environment: 'node24.18.0-windows',
    status: 'FAIL',
  })
  assert.equal((await verifyTraceability(t, { boundary, snapshot: current })).ok, true)
  assert.ok(
    issue(
      await verifyTraceability(t, {
